fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> Vec<char> {
    // Convert target width to usize for comparison with orig.len()
    let w = width as usize;
    let len = orig.len();

    // If the original is already at least as long as the target width,
    // return it unchanged.
    if len >= w {
        orig
    } else {
        // Otherwise, allocate a new Vec with the desired capacity
        let mut res = Vec::with_capacity(w);
        // Compute how many fill characters we need
        let pad = w - len;
        // Push the fill characters
        for _ in 0..pad {
            res.push(fillchar);
        }
        // Append the original characters so they become the suffix
        res.extend(orig);
        res
    }
}